// UX13.3-4 (t_af88952d): the translation keys the signed-out auth pages (/auth/login, /signup)
// can ask for. The (auth-page-wrapper) layout ships only these, not the whole 4.7k-key common.json
// (~86 KB gz in the RSC payload). authKeys.json is generated by this scanner; the vitest test
// re-runs it and fails if the committed file is stale, i.e. a new t("literal") was added
// to a file these pages render without regenerating:  node apps/web/app/auth-i18n/scanAuthKeys.mjs --write
import { readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "../../../..");

// Everything the two pages render on the client. Directories are scanned recursively.
export const SCAN_PATHS = [
  "apps/web/modules/auth/login-view.tsx",
  "apps/web/modules/signup-view.tsx",
  "apps/web/modules/auth/components",
  "apps/web/modules/auth/hooks/useLastUsed.tsx",
  "apps/web/components/auth",
  "apps/web/components/AddToHomescreen.tsx",
  "apps/web/lib/app-providers-app-dir.tsx",
  "apps/web/app/providers.tsx",
  "packages/lib/components/ServerTrans.tsx",
  "packages/ui/components/form",
  "packages/ui/components/alert",
  "packages/ui/components/toast",
  "packages/ui/components/logo",
  "packages/ui/components/icon",
  "packages/ui/components/button",
  "packages/ui/components/tooltip",
  "packages/coss-ui/src/components",
];

// Keys that are not a t("literal") in a scanned file: the signup FEATURES table (t(feature.title)),
// the ErrorCode values (login errors arrive as codes and are looked up by code), and the
// ternary in the data-region select.
export const EXTRA_KEYS = [
  "connect_all_calendars",
  "connect_all_calendars_description",
  "set_availability",
  "set_availbility_description",
  "share_a_link_or_embed",
  "share_a_link_or_embed_description",
  "european_union",
  "united_states",
  "signing_up_terms",
];
export const ERROR_CODE_FILE = "packages/features/auth/lib/ErrorCode.ts";

const SKIP = /\.(test|spec|stories)\.[tj]sx?$|__tests__|__mocks__/;
const FILE = /\.(tsx?|mjs)$/;

function walk(p, out) {
  const st = statSync(p);
  if (st.isDirectory()) {
    for (const f of readdirSync(p)) walk(join(p, f), out);
  } else if (FILE.test(p) && !SKIP.test(p)) out.push(p);
}

export function scanKeys() {
  const files = [];
  for (const p of SCAN_PATHS) walk(join(root, p), files);
  const keys = new Set(EXTRA_KEYS);
  const re = /(?:\bt|\bgetFixedT\([^)]*\)|i18nKey=|i18nKey:)\s*\(?\s*\{?\s*["'`]([A-Za-z0-9_.:-]+)["'`]/g;
  const reCall = /\bt\(\s*\n?\s*["'`]([A-Za-z0-9_]+)["'`]/g;
  for (const f of files) {
    const src = readFileSync(f, "utf8");
    for (const m of src.matchAll(re)) keys.add(m[1]);
    for (const m of src.matchAll(reCall)) keys.add(m[1]);
  }
  // ErrorCode values: both the raw code and the underscore form used as a key.
  const ec = readFileSync(join(root, ERROR_CODE_FILE), "utf8");
  for (const m of ec.matchAll(/=\s*"([a-z0-9_-]+)"/g)) {
    keys.add(m[1]);
    keys.add(m[1].replace(/-/g, "_"));
  }
  const en = JSON.parse(readFileSync(join(root, "packages/i18n/locales/en/common.json"), "utf8"));
  // Keep only keys that exist in common.json: anything else cannot resolve anyway.
  return [...keys].filter((k) => k in en).sort();
}

if (process.argv[1] === fileURLToPath(import.meta.url) && process.argv.includes("--write")) {
  const keys = scanKeys();
  writeFileSync(join(here, "authKeys.json"), `${JSON.stringify(keys, null, 2)}\n`);
  console.log(`authKeys.json: ${keys.length} keys`);
}
